/bin/bash -lc "node --input-type=module <<'JS'
import { JSDOM } from '/tmp/calendar-check/node_modules/jsdom/lib/api.js';
import { createServer } from 'vite';
import React, { act } from 'react';
import { createRoot } from 'react-dom/client';
import assert from 'node:assert/strict';
const dom = new JSDOM('<div id=\"root\"></div>', { pretendToBeVisual: true });
Object.assign(globalThis, { window: dom.window, document: dom.window.document, HTMLElement: dom.window.HTMLElement, requestAnimationFrame: dom.window.requestAnimationFrame.bind(dom.window), IS_REACT_ACT_ENVIRONMENT: true });
const server = await createServer({ server: { middlewareMode: true } });
try {
  const { App } = await server.ssrLoadModule('/src/App.tsx');
  const root = createRoot(document.getElementById('root'));
  await act(async () => root.render(React.createElement(App)));
  const click = async element => act(async () => { element.click(); await new Promise(resolve => setTimeout(resolve, 30)); });
  const byLabel = label => document.querySelector("'`[aria-label="${label}"]`);
  assert.match(document.querySelector('"'[role=\"status\"]').textContent, /Дата не выбрана/);
  const firstMonth = document.querySelector('h2').textContent;
  await click(byLabel('Следующий месяц'));
  assert.notEqual(document.querySelector('h2').textContent, firstMonth);
  await click(byLabel('Предыдущий месяц'));
  assert.equal(document.querySelector('h2').textContent, firstMonth);
  await click(document.querySelector('.calendar-day:not(.outside-month)'));
  assert.equal(document.querySelectorAll('[aria-pressed=\"true\"]').length, 1);
  assert.doesNotMatch(document.querySelector('[role=\"status\"]').textContent, /Дата не выбрана/);
  const focusedBefore = document.activeElement;
  await act(async () => {
    focusedBefore.dispatchEvent(new dom.window.KeyboardEvent('keydown', { key: 'ArrowRight', bubbles: true }));
    await new Promise(resolve => setTimeout(resolve, 30));
  });
  assert.notEqual(document.activeElement, focusedBefore);
  assert.equal(document.activeElement.textContent.trim(), '2');
  await click(document.querySelector('.clear-action'));
  assert.match(document.querySelector('[role=\"status\"]').textContent, /Дата не выбрана/);
  await click([...document.querySelectorAll('button')].find(button => button.textContent === 'Сегодня'));
  assert.equal(document.querySelector('[aria-current=\"date\"]').getAttribute('aria-pressed'), 'true');
  const adjacent = document.querySelector('.outside-month');
  if (adjacent) {
    const label = adjacent.getAttribute('aria-label');
    await click(adjacent);
    assert.equal(document.querySelector('[aria-pressed=\"true\"]').getAttribute('aria-label'), label);
    assert.equal(document.querySelector('[aria-pressed=\"true\"]').classList.contains('outside-month'), false);
  }
  await act(async () => root.unmount());
  console.log('PASS: month navigation, date selection, keyboard navigation, clear, today, adjacent-month selection.');
} finally { await server.close(); dom.window.close(); }
JS"

